//! Renders the documentation pages. A debug build uses Propel's dev renderer,
//! which reads the views from `resources/views` on each request. A release build
//! renders the views compiled by `build.rs`.

use propel_rocket::PropelView;

use crate::nav::DocPage;

/// The compiled views, generated by `build.rs` from `resources/views`.
#[allow(dead_code, unused_imports, clippy::all)]
pub(crate) mod compiled {
    include!(concat!(env!("OUT_DIR"), "/propel_views.rs"));
}

/// Renders the view `name` with the page's context.
#[cfg(debug_assertions)]
pub(crate) fn render_page(name: &str, context: &DocPage) -> PropelView {
    PropelView::render(name, context)
}

/// Renders the view `name` with the page's context, from the compiled view. An
/// unknown name is a bug in a route, so it panics.
#[cfg(not(debug_assertions))]
pub(crate) fn render_page(name: &str, context: &DocPage) -> PropelView {
    let assets = propel_runtime::Assets::new("public");
    let rendered = match name {
        "docs.introduction" => compiled::docs::introduction::render(context, &assets),
        "docs.install" => compiled::docs::install::render(context, &assets),
        "docs.panel" => compiled::docs::panel::render(context, &assets),
        "docs.resources" => compiled::docs::resources::render(context, &assets),
        "docs.forms" => compiled::docs::forms::render(context, &assets),
        "docs.tables" => compiled::docs::tables::render(context, &assets),
        "docs.actions" => compiled::docs::actions::render(context, &assets),
        "docs.notifications" => compiled::docs::notifications::render(context, &assets),
        "docs.widgets" => compiled::docs::widgets::render(context, &assets),
        "docs.views" => compiled::docs::views::render(context, &assets),
        "errors.not_found" => compiled::errors::not_found::render(context, &assets),
        other => panic!("no compiled view named `{other}`"),
    };
    PropelView::from_result(rendered)
}
